<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {BookOpen,Plus,ArrowLeft,Download,History} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import type {Document} from '../domain/local-contract'
import {importLorebook,exportLorebook,validateLorebook,type LocalLorebook,type LoreEntry} from '../prompt-runtime/lorebook'
const store=useLocal(),books=ref<Document<LocalLorebook>[]>([]),editing=ref<LocalLorebook|null>(null),editingId=ref(''),revision=ref(0),error=ref(''),busy=ref(false),search=ref(''),defaults=ref<Document<{lorebookIds:string[]}>|null>(null),historyOpen=ref(false),historic=ref<Document<LocalLorebook>|null>(null),historicVersion=ref(1)
const visible=computed(()=>books.value.filter(row=>row.value.name.toLowerCase().includes(search.value.toLowerCase()))),controller=new AbortController();let disposed=false
async function load(){const vault=store.vault;if(!vault)return;const [rows,global]=await Promise.all([vault.list<LocalLorebook>('lorebook'),vault.read<{lorebookIds:string[]}>('settings:lorebooks')]);if(disposed||store.vault!==vault)return;books.value=rows.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));defaults.value=global}
function edit(row?:Document<LocalLorebook>){editing.value=row?JSON.parse(JSON.stringify(row.value)):importLorebook('{"spec":"lorebook_v3","data":{"name":"新世界书","entries":[]}}');editingId.value=row?.id||crypto.randomUUID();revision.value=row?.revision||0;historyOpen.value=false;historic.value=null;error.value=''}
function addEntry(){editing.value?.entries.push({id:crypto.randomUUID(),keys:[],secondaryKeys:[],logic:'any',content:'',enabled:true,constant:false,caseSensitive:false,useRegex:false,probability:100,priority:0,order:editing.value.entries.length,position:'after_char',speakerIds:[],cooldown:0,delay:0,source:{extensions:{},selective:true}})}
function setKeys(entry:LoreEntry,key:'keys'|'secondaryKeys'|'speakerIds',event:Event){entry[key]=(event.target as HTMLInputElement).value.split(',').map(value=>value.trim()).filter(Boolean);if(key==='secondaryKeys')entry.source.selective=entry[key].length>0}
async function save(){const vault=store.vault;if(!vault||!editing.value||busy.value)return;busy.value=true;error.value='';try{validateLorebook(editing.value);exportLorebook(editing.value);await vault.commitBundle(crypto.randomUUID(),[{kind:'lorebook',id:editingId.value,expectedRevision:revision.value,value:editing.value}],controller.signal);if(disposed||store.vault!==vault)return;editing.value=null;await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
async function toggleGlobal(row:Document<LocalLorebook>){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;try{const ids=defaults.value?.value.lorebookIds||[],next=ids.includes(row.id)?ids.filter(id=>id!==row.id):[...ids,row.id];await vault.commitBundle(crypto.randomUUID(),[{kind:'settings',id:'settings:lorebooks',expectedRevision:defaults.value?.revision||0,value:{lorebookIds:next}}],controller.signal);await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
async function toggleEnabled(row:Document<LocalLorebook>){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;try{await vault.commitBundle(crypto.randomUUID(),[{kind:'lorebook',id:row.id,expectedRevision:row.revision,value:{...row.value,enabled:!row.value.enabled}}],controller.signal);await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
async function upload(event:Event){const input=event.target as HTMLInputElement,vault=store.vault;if(!vault||busy.value)return;busy.value=true;error.value='';const failures:string[]=[];try{for(const file of Array.from(input.files||[])){controller.signal.throwIfAborted();try{if(file.size>8*1024*1024)throw new Error('世界书超过 8 MiB');const book=importLorebook(await file.text());await vault.commitBundle(crypto.randomUUID(),[{kind:'lorebook',id:crypto.randomUUID(),expectedRevision:0,value:book}],controller.signal)}catch(e){if(controller.signal.aborted)throw e;failures.push(file.name+'：'+(e as Error).message)}}await load();error.value=failures.join('；')}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false;input.value=''}}
function download(row:Document<LocalLorebook>){try{const url=URL.createObjectURL(new Blob([exportLorebook(row.value)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=row.value.name+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=(e as Error).message}}
async function viewHistory(){const vault=store.vault;if(!vault)return;historyOpen.value=true;historicVersion.value=Math.max(1,revision.value-1);historic.value=await vault.read<LocalLorebook>(editingId.value,historicVersion.value)}
async function pickVersion(){const vault=store.vault;if(!vault)return;const row=await vault.read<LocalLorebook>(editingId.value,Number(historicVersion.value));if(!disposed)historic.value=row}
function restoreVersion(){if(historic.value){editing.value=JSON.parse(JSON.stringify(historic.value.value));historyOpen.value=false;error.value='已放入编辑器；保存将创建新版本'}}
onMounted(()=>void load().catch(e=>error.value=(e as Error).message));onUnmounted(()=>{disposed=true;controller.abort()})
</script>
<template><section>
<div class="final-page-heading"><div class="final-heading-copy"><span class="final-eyebrow">WORLDBOOKS</span><h1>{{editing?editing.name:'世界书'}}</h1></div><div class="final-page-actions"><button v-if="editing" @click="editing=null"><ArrowLeft :size="18"/>返回</button><button v-else class="final-primary" @click="edit()"><Plus :size="18"/>新建</button></div></div>
<p v-if="error" class="final-error" role="alert">{{error}}</p>
<form v-if="editing" class="final-card-form" @submit.prevent="save"><label>名称<input v-model="editing.name" maxlength="200" required></label><div class="final-grid-row"><label>扫描最近消息<input v-model.number="editing.scanDepth" type="number" min="1" max="1000" required></label><label>世界书保守 token 上限<input v-model.number="editing.tokenBudget" type="number" min="0" max="1000000" required></label></div><label class="final-check"><input v-model="editing.enabled" type="checkbox">启用世界书</label><label class="final-check"><input v-model="editing.recursive" type="checkbox">递归触发</label>
<article v-for="(entry,index) in editing.entries" :key="entry.id" class="final-lore-entry"><div class="final-section-title"><strong>条目 {{index+1}}</strong><button type="button" @click="editing.entries.splice(index,1)">移除</button></div><label>关键词<input :value="entry.keys.join(', ')" maxlength="1000" placeholder="逗号分隔" @change="setKeys(entry,'keys',$event)"></label><label>内容<textarea v-model="entry.content" maxlength="200000" rows="5"></textarea></label><div class="final-grid-actions"><label class="final-check"><input v-model="entry.enabled" type="checkbox">启用</label><label class="final-check"><input v-model="entry.constant" type="checkbox">常驻</label></div><details><summary>触发与插入设置</summary><div class="final-card-form"><label>二级关键词<input :value="entry.secondaryKeys.join(', ')" @change="setKeys(entry,'secondaryKeys',$event)"></label><label>二级条件<select v-model="entry.logic"><option value="any">任一命中</option><option value="all">全部命中</option><option value="none">全部不命中</option><option value="not_all">至少一个不命中</option></select></label><div class="final-grid-actions"><label class="final-check"><input v-model="entry.caseSensitive" type="checkbox">区分大小写</label><label class="final-check"><input v-model="entry.useRegex" type="checkbox">关键词使用正则</label></div><label>插入位置<select v-model="entry.position"><option value="before_char">角色设定前</option><option value="after_char">角色设定后</option><option value="after_history">聊天历史后</option></select></label><div class="final-grid-row"><label>概率 %<input v-model.number="entry.probability" type="number" min="0" max="100"></label><label>优先级<input v-model.number="entry.priority" type="number"></label><label>插入顺序<input v-model.number="entry.order" type="number"></label><label>冷却请求数<input v-model.number="entry.cooldown" type="number" min="0" max="10000"></label><label>延迟请求数<input v-model.number="entry.delay" type="number" min="0" max="10000"></label></div><label>可知情角色身份 ID<input :value="entry.speakerIds.join(', ')" placeholder="留空为所有角色；逗号分隔" @change="setKeys(entry,'speakerIds',$event)"></label></div></details></article>
<button type="button" @click="addEntry"><Plus :size="16"/>添加条目</button><div class="final-grid-actions"><button class="final-primary" :disabled="busy">保存世界书</button><button v-if="revision>1" type="button" @click="viewHistory"><History :size="16"/>版本</button></div><section v-if="historyOpen" class="final-import-panel"><label>历史版本<select v-model="historicVersion" @change="pickVersion"><option v-for="version in revision" :key="version" :value="version">版本 {{version}}</option></select></label><pre class="final-task-prose">{{historic?.value.name}} · {{historic?.value.entries.length}} 个条目
{{historic?.value.entries.map(row=>row.content).join('\n\n')}}</pre><button type="button" @click="restoreVersion">恢复到编辑器</button></section></form>
<template v-else><RouterLink to="/local/characters" class="final-text-link">返回角色</RouterLink><label class="final-import-panel">导入 JSON 世界书<input type="file" accept=".json" multiple :disabled="busy" @change="upload"></label><label v-if="books.length" class="final-search">搜索世界书<input v-model="search" type="search"></label><div v-if="!books.length" class="final-empty"><BookOpen :size="40"/><h2>给故事留一本手记</h2><button class="final-primary" @click="edit()">创建世界书</button></div><div class="final-collection-grid"><article v-for="row in visible" :key="row.id" class="final-character-card"><BookOpen :size="28"/><h2>{{row.value.name}}</h2><span class="final-subtle">{{row.value.entries.length}} 条 · 版本 {{row.revision}} · {{row.value.enabled?'已启用':'已停用'}}</span><div class="final-grid-actions"><button @click="edit(row)">编辑</button><button :disabled="busy" @click="toggleEnabled(row)">{{row.value.enabled?'停用':'启用'}}</button><button class="final-icon-button" :aria-label="'导出'+row.value.name" @click="download(row)"><Download :size="18"/></button></div><button :disabled="busy" :aria-pressed="!!defaults?.value.lorebookIds.includes(row.id)" @click="toggleGlobal(row)">{{defaults?.value.lorebookIds.includes(row.id)?'移除全局绑定':'绑定所有对话'}}</button></article></div></template>
</section></template>
